changeSet.sql:
ALTER TABLE tnt_incidents ADD COLUMN IF NOT EXISTS blocking                   BOOLEAN NOT NULL DEFAULT FALSE;
ALTER TABLE tnt_incidents ADD COLUMN IF NOT EXISTS blocking_forced_by_courier BOOLEAN NOT NULL DEFAULT FALSE;
ALTER TABLE tnt_incidents ADD COLUMN IF NOT EXISTS delivery_outcome           VARCHAR(20);
ALTER TABLE tnt_incidents ADD COLUMN IF NOT EXISTS responsible_party          VARCHAR(20);
ALTER TABLE tnt_incidents ADD COLUMN IF NOT EXISTS resolution_note            TEXT;
ALTER TABLE tnt_incidents ADD COLUMN IF NOT EXISTS resolution_proposed_at     TIMESTAMPTZ;
ALTER TABLE tnt_incidents ADD COLUMN IF NOT EXISTS event_sequence             BIGINT NOT NULL DEFAULT 0;
UPDATE tnt_incidents SET blocking = TRUE
 WHERE status NOT IN ('CLOSED', 'CANCELLED') AND blocking = FALSE AND event_sequence = 0;

CREATE INDEX IF NOT EXISTS idx_tnt_incidents_pending_confirmation
    ON tnt_incidents (resolution_proposed_at)
    WHERE status = 'PENDING_CONFIRMATION';
